t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
Pf={'1':np.ones_like(P),'P':P,'P2':P**2,'sP':np.sqrt(P),'lP':np.log(P),'PlP':P*np.log(P),'P3':P**3}
Tf={'1':np.ones_like(t),'t':t,'st':np.sqrt(t),'t2':t**2,'it':1/t,'lt':np.log(t),'et':np.exp(-t)}
names=[];cols=[]
for a in Pf:
    for b in Tf:
        names.append(a+'*'+b); cols.append(Pf[a]*Tf[b])
M=np.column_stack(cols)
c,_,_,_=np.linalg.lstsq(M,y,rcond=None)
print('full',np.mean((M@c-y)**2)/np.var(y))
# greedy forward selection
sel=[]
for k in range(10):
    bestE=None
